<script module lang="ts">
/**
 * A phone number, reported as one E.164 string (`design/components/phone-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/phone-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  afterRender,
  agentMember,
  commitPhone,
  composingKey,
  devWarning,
  isPhoneValue,
  joinSlot,
  phoneCountries,
  phoneCountryOptions,
  phoneDefaultCountry,
  phoneDraft,
  readPhone,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/phone-input.module.css'
import Combobox from './Combobox.svelte'
import Input from './Input.svelte'

export interface PhoneInputMessages {
  country?: string
  showCountries?: string
  countriesShown?: (count: number) => string
  noCountry?: string
}

export interface PhoneInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * The regions offered, in this order. Every region, sorted by name, when omitted.
   */
  countries?: string[]
  /**
   * ISO 3166-1 alpha-2. The country shown before the reader chooses one, while the value names
   * none. Defaults to the first of `countries`, else the United States.
   */
  defaultCountry?: string
  defaultValue?: string
  disabled?: boolean
  /**
   * On the number's `<input>`, so a link to the field reaches a control that takes focus.
   */
  id?: string
  invalid?: boolean
  /**
   * The language of the country names and of their order.
   */
  locale?: string
  /**
   * Every word the member writes itself. See `PhoneInputMessages`.
   */
  messages?: PhoneInputMessages
  /**
   * Serializes the committed E.164 value in one hidden input.
   */
  name?: string
  /**
   * Reports commits, never drafts, as NumberInput does: the reader leaves the number or presses
   * Enter in it, chooses a country, or pastes a number written with its calling code. It fires
   * only for a value that differs from the one the field holds.
   */
  onChange?: (value: string) => void
  /**
   * The number stays focusable and selectable, and the country is shown as read-only text.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * An E.164 string (`+442079460958`), or the empty string while the national number has no
   * digits. A value that is not E.164 is drawn as well as it can be, with a development warning.
   */
  value?: string
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  countries,
  defaultCountry,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  locale,
  messages,
  name,
  onChange,
  readOnly = false,
  size = 'md',
  value,
}: PhoneInputProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let browserLanguage = $state(undefined as string | undefined)
// svelte-ignore state_referenced_locally
let kept = $state(defaultValue ?? '')
// svelte-ignore state_referenced_locally
let chosen = $state(
  readPhone(value ?? defaultValue ?? '', {
    country: phoneDefaultCountry(defaultCountry, countries),
    countries,
  }).country,
)
let draft = $state(null as string | null)
let typed = $state(null as { text: string; under: string } | null)
let root = $state<HTMLElement | null>(null)
const language = $derived(locale ?? browserLanguage ?? 'en-US')
const say = $derived({
  country: 'Country calling code',
  showCountries: 'Show countries',
  countriesShown: (count: number) => `${count} countries`,
  noCountry: 'No matching country',
  ...messages,
})
const current = $derived(value ?? kept)
const drawn = $derived(readPhone(current, { country: chosen, countries }))
const country = $derived(drawn.country)
const national = $derived(draft ?? drawn.national)
const options = $derived(phoneCountryOptions({ locale: language, countries, include: country }))
const countryLabel = $derived(options.find((option) => option.value === country)?.label ?? '')
const countryText = $derived(typed !== null && typed.under === country ? typed.text : countryLabel)
const countryId = $derived(`${uid}-country`)
const countryLabelledby = $derived(
  ariaLabelledby === undefined ? undefined : `${countryId} ${ariaLabelledby}`,
)
const commit = $derived((next: string, text: string): void => {
  const result = commitPhone(next, text, { countries })
  chosen = result.country
  draft = result.value === '' && result.national !== '' ? result.national : null
  if (result.value !== current) {
    kept = result.value
    onChange?.(result.value)
  }
})
const commitDraft = $derived((): void => {
  if (draft !== null) commit(country, draft)
})
const fitNumber = $derived((event: Event): void => {
  const field = event.target
  if (field instanceof HTMLInputElement && field.type === 'tel')
    afterRender(() => {
      if (field.value !== national) field.value = national
    })
})
const pasteInto = $derived((event: ClipboardEvent): void => {
  const field = event.target
  if (readOnly || !(field instanceof HTMLInputElement) || field.type !== 'tel') return
  const pasted = event.clipboardData?.getData('text/plain') ?? ''
  event.preventDefault()
  if (pasted.trimStart().startsWith('+')) {
    const result = commitPhone(country, pasted, { countries })
    if (result.value === '') draft = result.national
    else commit(country, pasted)
    return
  }
  const start = field.selectionStart ?? national.length
  const end = field.selectionEnd ?? national.length
  draft = phoneDraft(`${national.slice(0, start)}${pasted}${national.slice(end)}`, country)
})
const effect1 = () => {
  browserLanguage = globalThis.navigator?.language
}
watchEffect(effect1)
const effect2 = () => {
  devWarning(
    current !== '' && !isPhoneValue(current),
    `PhoneInput: the value "${current}" is not an E.164 string. Pass +, the calling code and the national number, or the empty string.`,
  )
}
watchEffect(effect2, { watch: () => current })
const effect3 = () => {
  devWarning(
    countries !== undefined && phoneCountries(countries).length !== countries.length,
    'PhoneInput: `countries` repeats a region or names one with no calling code. Each is listed once, and those are dropped.',
  )
}
watchEffect(effect3, { watch: () => countries })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'PhoneInput',
    element: () => root,
    state: () => ({
      value: current,
      country: country,
      disabled: disabled,
      invalid: invalid,
      readonly: readOnly,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (readOnly) throw new Error('The field is read-only.')
            if (commitPhone(country, value, { countries }).value === '') {
              throw new Error(`"${value}" is not a phone number the field can read.`)
            }
            commit(country, value)
          })(),
      },
      clear: () =>
        (() => {
          if (readOnly) throw new Error('The field is read-only.')
          commit(country, '')
        })(),
    },
    withholds: () => root,
  })
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    role="group"
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-readonly={(readOnly) ? '' : undefined}
    data-member="phone-input"
    ><span class={styles.country}
      >{#if readOnly
        }<Input
          value={countryLabel}
          readOnly={true}
          {size}
          {invalid}
          {disabled}
          id={countryId}
          aria-label={say.country}
          aria-labelledby={countryLabelledby}
          aria-describedby={ariaDescribedby}
      />{:else
        }<Combobox
          {options}
          value={country}
          inputValue={countryText}
          {size}
          {invalid}
          {disabled}
          id={countryId}
          messages={{ showOptions: say.showCountries, options: say.countriesShown }}
          emptyMessage={say.noCountry}
          aria-label={say.country}
          aria-labelledby={countryLabelledby}
          aria-describedby={ariaDescribedby}
          onChange={(event) => { event !== null && commit(event, national) }}
          onInputChange={(event) => { typed = { text: event, under: country } }}
      />{/if
    }</span
    ><span
      class={styles.number}
      onkeydown={(event) => { if (event.key === 'Enter' && !composingKey(event)) commitDraft() }}
      onpaste={(event) => { pasteInto(event) }}
      oninput={(event) => { fitNumber(event) }}
      ><Input
        type="tel"
        value={national}
        {size}
        {invalid}
        {disabled}
        {readOnly}
        {id}
        autoComplete="tel-national"
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledby}
        aria-describedby={ariaDescribedby}
        aria-required={ariaRequired}
        onChange={(event) => { draft = phoneDraft(event, country) }}
        onBlur={() => { commitDraft() }}
    /></span
    >{#if name !== undefined
      }<input type="hidden" {name} value={current} disabled={disabled || undefined}
    />{/if
  }</div
>{/if
}{@render joined.end?.()}
